1	//! op-mcp-shim — MCP (stdio) ⇄ gRPC bridge driven entirely by server reflection.
2	//!
3	//! Spawned by MCP clients (claude-code, gemini CLI, factory/droid) as a stdio
4	//! server. On tools/list it reflects the target gRPC endpoint and projects
5	//! every unary RPC as an MCP tool (schema derived from the proto descriptors);
6	//! tools/call builds a DynamicMessage from the JSON arguments and invokes the
7	//! method. New RPCs on the server appear as tools with no rebuild here.
8	//!
9	//! Identity: x-ghostbridge-* headers are normally injected in-path by xray.
10	//! For direct connections set GHOSTBRIDGE_FOOTPRINT / GHOSTBRIDGE_TRACE_ID or
11	//! pass --header.
12	
13	mod codec;
14	mod discovery;
15	mod schema;
16	
17	use std::str::FromStr;
18	
19	use clap::Parser;
20	use prost_reflect::{DescriptorPool, DynamicMessage, MethodDescriptor};
21	use serde_json::{json, Value};
22	use tokio::io::{AsyncBufReadExt, BufReader};
23	use tonic::codegen::http::uri::PathAndQuery;
24	use tonic::metadata::{Ascii, MetadataKey, MetadataValue};
25	use tonic::transport::{Channel, ClientTlsConfig, Endpoint};
26	
27	#[derive(Parser)]
28	#[command(version, about = "MCP stdio shim over gRPC reflection")]
29	struct Cli {
30	    /// Target gRPC endpoint (tonic-web listener also accepts native gRPC)
31	    #[arg(
32	        long,
33	        env = "MCP_GRPC_ENDPOINT",
34	        default_value = "http://10.200.0.1:50052"
35	    )]
36	    endpoint: String,
37	
38	    /// Extra request metadata, repeatable: --header k=v
39	    #[arg(long = "header", value_name = "K=V")]
40	    headers: Vec<String>,
41	
42	    /// Only expose services whose full name contains this substring (repeatable)
43	    #[arg(long = "service")]
44	    services: Vec<String>,
45	}
46	
47	struct Shim {
48	    channel: Channel,
49	    headers: Vec<(String, String)>,
50	    service_filter: Vec<String>,
51	    pool: Option<DescriptorPool>,
52	}
53	
54	#[tokio::main]
55	async fn main() -> anyhow::Result<()> {
56	    let cli = Cli::parse();
57	
58	    let mut endpoint: Endpoint = Channel::from_shared(cli.endpoint.clone())?;
59	    if cli.endpoint.starts_with("https://") {
60	        endpoint = endpoint.tls_config(ClientTlsConfig::new().with_native_roots())?;
61	    }
62	    let channel = endpoint.connect_lazy();
63	
64	    let mut headers: Vec<(String, String)> = Vec::new();
65	    for h in &cli.headers {
66	        let (k, v) = h
67	            .split_once('=')
68	            .ok_or_else(|| anyhow::anyhow!("--header must be k=v, got {h:?}"))?;
69	        headers.push((k.to_string(), v.to_string()));
70	    }
71	    for (env, key) in [
72	        ("GHOSTBRIDGE_FOOTPRINT", "x-ghostbridge-footprint"),
73	        ("GHOSTBRIDGE_TRACE_ID", "x-ghostbridge-trace-id"),
74	    ] {
75	        if let Ok(v) = std::env::var(env) {
76	            if !headers.iter().any(|(k, _)| k == key) {
77	                headers.push((key.to_string(), v));
78	            }
79	        }
80	    }
81	
82	    eprintln!("op-mcp-shim: target {}", cli.endpoint);
83	
84	    let mut shim = Shim {
85	        channel,
86	        headers,
87	        service_filter: cli.services,
88	        pool: None,
89	    };
90	    shim.run().await
91	}
92	
93	impl Shim {
94	    async fn run(&mut self) -> anyhow::Result<()> {
95	        let mut lines = BufReader::new(tokio::io::stdin()).lines();
96	        while let Some(line) = lines.next_line().await? {
97	            if line.trim().is_empty() {
98	                continue;
99	            }
100	            let req: Value = match serde_json::from_str(&line) {
101	                Ok(v) => v,
102	                Err(e) => {
103	                    respond_err(&Value::Null, -32700, &format!("parse error: {e}"));
104	                    continue;
105	                }
106	            };
107	            let id = req.get("id").cloned();
108	            let method = req.get("method").and_then(Value::as_str).unwrap_or("");
109	            let params = req.get("params").cloned().unwrap_or_else(|| json!({}));
110	
111	            if method.starts_with("notifications/") {
112	                continue;
113	            }
114	            let result = match method {
115	                "initialize" => Ok(self.initialize(&params)),
116	                "ping" => Ok(json!({})),
117	                "tools/list" => self.tools_list().await,
118	                "tools/call" => self.tools_call(&params).await,
119	                "resources/list" => Ok(json!({"resources": []})),
120	                "prompts/list" => Ok(json!({"prompts": []})),
121	                other => Err(format!("method not found: {other}")),
122	            };
123	            let Some(id) = id else { continue };
124	            match result {
125	                Ok(value) => respond_ok(&id, value),
126	                Err(msg) => respond_err(&id, -32603, &msg),
127	            }
128	        }
129	        Ok(())
130	    }
131	
132	    fn initialize(&self, params: &Value) -> Value {
133	        let version = params
134	            .get("protocolVersion")
135	            .and_then(Value::as_str)
136	            .unwrap_or("2024-11-05");
137	        json!({
138	            "protocolVersion": version,
139	            "capabilities": {"tools": {"listChanged": false}},
140	            "serverInfo": {"name": "op-mcp-shim", "version": env!("CARGO_PKG_VERSION")}
141	        })
142	    }
143	
144	    async fn ensure_pool(&mut self) -> Result<&DescriptorPool, String> {
145	        if self.pool.is_none() {
146	            let pool = discovery::build_pool(self.channel.clone())
147	                .await
148	                .map_err(|e| format!("reflection discovery failed: {e:#}"))?;
149	            self.pool = Some(pool);
150	        }
151	        Ok(self.pool.as_ref().unwrap())
152	    }
153	
154	    fn methods(pool: &DescriptorPool, filter: &[String]) -> Vec<(String, MethodDescriptor)> {
155	        let mut out = Vec::new();
156	        for svc in pool.services() {
157	            let full = svc.full_name();
158	            if full.starts_with("grpc.reflection") || full.starts_with("grpc.health") {
159	                continue;
160	            }
161	            if !filter.is_empty() && !filter.iter().any(|f| full.contains(f.as_str())) {
162	                continue;
163	            }
164	            for m in svc.methods() {
165	                if m.is_client_streaming() || m.is_server_streaming() {
166	                    continue;
167	                }
168	                out.push((format!("{}_{}", svc.name(), m.name()), m));
169	            }
170	        }
171	        out
172	    }
173	
174	    async fn tools_list(&mut self) -> Result<Value, String> {
