        debug!(
            tool = tool_name,
            attempt = attempt + 1,
            max_attempts = self.config.retry.max_retries + 1,
            "Calling tool"
        );

        let request = self
            .http
            .post(&url)
            .header("X-Client-ID", &self.config.client_id)
            .header("Content-Type", "application/json");

