24	/// A configured unix-domain socket endpoint.
25	///
26	/// In the single-socket model, one shared socket (e.g.
27	/// `/run/ghostbridge/container.sock`) serves all services.  xray routes by
28	/// domain/SNI to the tonic-web gRPC bridge, which listens on this socket and
29	/// demuxes by gRPC service/method (via reflection).
30	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
31	pub struct SocketEndpoint {
32	    /// Filesystem path to the shared socket.
33	    #[schemars(
34	        description = "Filesystem path of the shared unix domain socket",
35	        example = &"/run/ghostbridge/container.sock",
36	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-path@v1")
37	    )]
38	    pub path: String,
39	    /// Local TCP port the backend service listens on inside its container.
40	    /// xray routes to the tonic-web gRPC bridge, which dials the socket
41	    /// natively — this port is metadata for the bridge, not an xray listener.
42	    #[schemars(
43	        range(min = 1, max = 65535),
44	        description = "Backend service TCP port (metadata for the gRPC bridge, not an xray listener)",
45	        example = 6334,
46	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-port@v1")
47	    )]
48	    pub port: u16,
49	    /// Transport protocol carried over the socket.
50	    #[serde(default = "default_protocol")]
