79	/// (see [`super::schemars_adapter`]). `port` bounds, field descriptions (from
80	/// doc comments) and `required` flags all come from the type — the struct is
81	/// the single source of truth. The frozen hand-rolled `unix_socket_schema()`
82	/// (test-only) guards this against drift via `derived_schema_matches_hand_rolled`.
83	pub fn unix_socket_schema_derived() -> PluginSchema {
