94	pub struct UnixSocketPlugin {
95	    /// Live listeners keyed by socket path. Holding the `UnixListener` keeps the
96	    /// socket bound for the lifetime of the plugin; dropping it tears it down.
97	    active: Arc<Mutex<HashMap<String, UnixListener>>>,
98	}
99	
100	impl UnixSocketPlugin {
101	    pub fn new() -> Self {
102	        Self {
103	            active: Arc::new(Mutex::new(HashMap::new())),
104	        }
105	    }
106	
107	    /// Read this plugin's desired socket set straight from the single active
108	    /// schema catalog in shared memory (zero-copy 1:1). The catalog is keyed by
109	    /// plugin name and each entry carries the schema-declared state.
110	    fn read_desired() -> UnixSocketState {
111	        let Ok(mut bytes) = std::fs::read(SHM_SCHEMA_PATH) else {
112	            return UnixSocketState::default();
113	        };
114	        let Ok(catalog) = simd_json::to_owned_value(&mut bytes) else {
115	            return UnixSocketState::default();
116	        };
117	        let Some(state) = catalog
118	            .get("unix_socket")
119	            .and_then(|versions| versions.as_array())
120	            .and_then(|versions| versions.last())
121	            .and_then(|schema| schema.get("example"))
122	        else {
123	            return UnixSocketState::default();
124	        };
125	        simd_json::serde::from_owned_value::<UnixSocketState>(state.clone()).unwrap_or_default()
126	    }
127	
128	    /// Bind a single endpoint, replacing any stale socket file. Returns `true`
129	    /// when a new listener was created.
130	    fn ensure_bound(
131	        active: &mut HashMap<String, UnixListener>,
132	        endpoint: &SocketEndpoint,
133	    ) -> Result<bool> {
134	        if active.contains_key(&endpoint.path) {
135	            return Ok(false);
136	        }
137	        if let Some(parent) = Path::new(&endpoint.path).parent() {
138	            std::fs::create_dir_all(parent)?;
139	        }
140	        if Path::new(&endpoint.path).exists() {
141	            std::fs::remove_file(&endpoint.path)?;
142	        }
143	        let listener = UnixListener::bind(&endpoint.path)?;
144	        listener.set_nonblocking(true)?;
145	        active.insert(endpoint.path.clone(), listener);
146	        info!(
147	            socket = %endpoint.path,
148	            port = endpoint.port,
149	            protocol = %endpoint.protocol,
150	            "bound unix socket endpoint"
151	        );
152	        Ok(true)
153	    }
154	
155	    /// Drop a listener and unlink its socket file. Returns `true` when removed.
156	    fn unbind(active: &mut HashMap<String, UnixListener>, path: &str) -> bool {
157	        if active.remove(path).is_some() {
158	            if let Err(error) = std::fs::remove_file(path) {
159	                warn!(socket = %path, %error, "failed to unlink unix socket file");
160	            }
161	            true
162	        } else {
163	            false
164	        }
165	    }
166	
167	    /// Reconcile the live listeners to exactly the supplied desired set.
168	    fn reconcile(&self, desired: &UnixSocketState) -> ApplyResult {
169	        let mut active = self.active.lock();
170	        let mut changes_applied = Vec::new();
171	        let mut errors = Vec::new();
172	
173	        let wanted: HashSet<String> = desired.sockets.iter().map(|s| s.path.clone()).collect();
174	
175	        for endpoint in &desired.sockets {
176	            match Self::ensure_bound(&mut active, endpoint) {
177	                Ok(true) => changes_applied.push(format!(
178	                    "created socket {} (port {}, {})",
179	                    endpoint.path, endpoint.port, endpoint.protocol
180	                )),
181	                Ok(false) => {}
182	                Err(error) => errors.push(format!(
183	                    "failed to create socket {}: {}",
184	                    endpoint.path, error
185	                )),
186	            }
187	        }
188	
189	        let stale: Vec<String> = active
190	            .keys()
191	            .filter(|path| !wanted.contains(*path))
192	            .cloned()
193	            .collect();
194	        for path in stale {
195	            if Self::unbind(&mut active, &path) {
196	                changes_applied.push(format!("removed socket {}", path));
197	            }
198	        }
199	
200	        ApplyResult {
201	            success: errors.is_empty(),
202	            changes_applied,
203	            errors,
204	            checkpoint: None,
205	        }
206	    }
207	}
